window.kbPageData["views/entry/k-40e7607a47ef3684"] = {"key":"entry/k-40e7607a47ef3684","state":{"route":"entry/k-40e7607a47ef3684"},"node":{"id":"k-40e7607a47ef3684","mode":"k","title":"“五位一体”总体布局","type":"事实与事件","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":["政治理论必刷100题#79"],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"tags":{"专题":["modern"],"主类":["事实与事件"],"出处性质":["专项题解析","机构注释"],"学科":["政治理论"],"来源主题":["党政制度与理论"],"资料类别":["政治理论专项","非时政"]},"seeAlso":["k-4cb2ef4d0c5ffc18"],"directorySummary":"党的十八大将生态文明建设纳入中国特色社会主义事业总体布局，形成经济建设、政治建设、文化建设、社会建设和生态文明建设“五位一体”的总体布局。","review":{"definition":"党的十八大将生态文明建设纳入中国特色社会主义事业总体布局，形成经济建设、政治建设、文化建设、社会建设和生态文明建设“五位一体”的总体布局。","explanation":"第79题①把党的十八大提出的“建设美丽中国”与党的十九大部署的社会主义现代化强国建设“两步走”目标混在了一起。十八大在总体布局上的部署，是把生态文明建设纳入“五位一体”。","references":[],"evidence":"将生态文明建设纳入中国特色社会主义事业“五位一体”总体布局。","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"8cff63008c52a13e","label":"“五位一体”总体布局","topic":"党政制度与理论","category":"非时政","text":"2.“五位一体”总体布局\n2012 年 11 月，党的十八大首次提出中国特色社会主义事业总布局是“五位一\n体”，即“经济建设、政治建设、文化建设、社会建设、生态文明建设”五个方面。\n“五位一体”总体布局是一个有机整体，经济建设是根本，政治建设是保障，文化建\n设是灵魂，社会建设是条件，生态文明建设是基础，统一于把我国建成富强民主文明\n和谐美丽的社会主义现代化强国的新目标。","source":{"doc":"41195a191a57c1c36332","first":4,"last":4,"page":4,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"questions":{"政治理论必刷100题#79":{"paper":"政治理论必刷100题","n":79,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",24],"asrc":["国省考政治理论必刷100题.pdf",82],"card":"c712792d79101a72fad0396e","links":[{"id":"k-40e7607a47ef3684","role":"解题依据","why":"这是党的十八大在生态文明建设总体布局方面的部署。"}]}},"terms":{"k-4cb2ef4d0c5ffc18":{"id":"k-4cb2ef4d0c5ffc18","mode":"k","type":"概念与词义","title":"“四个全面”战略布局","qs":[],"count":0}},"references":{},"topics":[{"slug":"modern","title":"中国式现代化与民生"}],"units":{"k-40e7607a47ef3684":[["政治理论必刷100题#79"]]}};
